export const ORDER_NOTE =
  'Порядок импортов — это порядок побочных эффектов, и лучше всего это видно на стилях: `import "./reset.css"`, потом библиотека со своими стилями, потом `./overrides.css`. Поменяли строки местами — поменялся каскад. Причём порядок в dev и в рабочей сборке может **разойтись**: в dev стили вставляются тегами `<style>` по мере выполнения модулей, а в сборке собираются в один файл в порядке обхода графа.';

/**
 * `await` на верхнем уровне — разбор, который тема раньше обещала «в теме про цикл событий»,
 * а там его не было. Порядок снят на Node 26.8.2 (см. шапку файла); задержка сделана
 * `await null`, а не таймером, чтобы порядок не зависел от времени.
 */
