export const SIDE_EFFECT_DEFINITION =
  '**Побочный эффект модуля — всё, что меняется снаружи просто оттого, что модуль выполнился, даже если ни один его экспорт никто не использует.** Это не то же самое, что бытовое «функция что-то меняет». Главное в определении другое: чтобы выбросить модуль, бандлер обязан доказать, что выполнять его незачем.';

export const SIDE_EFFECT_CODE = `// Что бандлер обязан считать эффектом:
window.myGlobal = {}                      // 1. изменение чего-то снаружи
Element.prototype.myHelper = function(){} //    патч прототипа
document.addEventListener('click', h)

import { register } from './registry.js'  // 2. регистрация в чужом реестре
register('widget', Widget)

import './styles.css'                     // 3. импорт ради эффекта
import 'core-js/stable'

const config = readConfig()               // 4. а вдруг readConfig пишет в глобал?
const x = someImportedObj.prop            // 5. а вдруг это геттер с эффектом?`;

