/* ──────────────── Раздел 1 · import maps: карта имён для браузера ────────────────
 *
 * Всё ниже снято в Chromium 153.0.8010.12 (Playwright 1.63): страницы и модули отдавались
 * перехватом запросов на выдуманном адресе, без сервера. Те же файлы, те же строки и тот же
 * вывод проверяет `tests/unit/modules.test.ts` (блок «import maps»).
 */

/** Файлы стенда: путь → текст. Печатаются на странице склейкой, исполняются тестом как есть. */
export const IMPORTMAP_FILES: Record<string, string> = {
  '/index.html': `<script type="importmap">
{
  "imports": {
    "vue": "/vendor/vue-3.js",
    "lodash/": "/vendor/lodash/"
  },
  "scopes": {
    "/legacy/": { "vue": "/vendor/vue-2.js" }
  }
}
</script>
<script type="module" src="/app/main.js"></script>`,
  '/app/main.js': `import { who } from 'vue'                // → /vendor/vue-3.js
import get from 'lodash/get.js'         // → /vendor/lodash/get.js
import { who as legacy } from '/legacy/widget.js'

console.log(who, legacy, get({ n: 1 }, 'n'))`,
  '/legacy/widget.js': `// то же имя 'vue' — но файл лежит в /legacy/, и срабатывает scope
import { who } from 'vue'               // → /vendor/vue-2.js
export { who }`,
  '/vendor/vue-3.js': `export const who = 'vue@3'`,
  '/vendor/vue-2.js': `export const who = 'vue@2'`,
  '/vendor/lodash/get.js': `export default (obj, key) => obj[key]`,
  '/vendor/dayjs.js': `export const name = 'dayjs'`,
};

/** Какие файлы показывать читателю — служебные заглушки пакетов в листинг не идут. */
const IMPORTMAP_SHOWN = ['/index.html', '/app/main.js', '/legacy/widget.js'];

export const IMPORTMAP_CODE = IMPORTMAP_SHOWN.map((path) =>
  (path.endsWith('.html') ? `<!-- ${path} -->\n` : `// ${path}\n`) + IMPORTMAP_FILES[path],
).join('\n\n');

/** Что напечатала страница — одна строка консоли. */
export const IMPORTMAP_OUT = 'vue@3 vue@2 1';

/** Вторая карта, добавленная, когда `vue` уже разрешён. Исполняется на той же странице. */
export const IMPORTMAP_LATE_CODE = `const late = document.createElement('script')
late.type = 'importmap'
late.textContent = JSON.stringify({
  imports: { vue: '/vendor/vue-2.js', dayjs: '/vendor/dayjs.js' },
})
document.head.append(late)

console.log((await import('vue')).who)     // старое правило осталось
console.log((await import('dayjs')).name)  // новое имя добавилось`;

export const IMPORTMAP_LATE_OUT = ['vue@3', 'dayjs'];

/** Предупреждение, которым Chromium 153 объясняет, куда делось правило для `vue`. */
